import './chroma-scope.js';
import {getLanguage,localizeProject} from './i18n.js';
import {projects} from './projects.js';
import {esc,icon,specList,tagLine,roomTitle,linkButton,insideButton,label} from './exhibit-frame.js';
const c=(zh,en)=>getLanguage()==='en'?en:zh;
export const chromaRepo='https://github.com/ChefDavid0815/chroma-monitor';
export const chromaRelease=`${chromaRepo}/releases/tag/v0.1.0`;
const mosaic=(count=56)=>`<div class="cm-mosaic" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="--i:${i};--tile:${['#fff000','#173dff','#ff273a','#00edff','#e9f2ff','#173dff'][i*7%6]}"></i>`).join('')}</div>`;
const signalDisc='<svg viewBox="0 0 200 200" aria-hidden="true"><path fill-rule="evenodd" d="M100 8a92 92 0 1 1 0 184 92 92 0 0 1 0-184Zm0 44a48 48 0 1 0 0 96 48 48 0 0 0 0-96Z"/><circle cx="100" cy="30" r="5" fill="#fff000"/><circle cx="170" cy="100" r="5" fill="#173dff"/><circle cx="100" cy="170" r="5" fill="#00edff"/></svg>';
const wave='<svg viewBox="0 0 360 90" preserveAspectRatio="none"><path d="M0 65H25l12-20 17 30 21-52 24 43 16-15h25l20-38 24 59 20-33 18 24h26l14-20 20 22 22-38 18 43h29"/><path d="M0 73h47l14-13 27 8 19-15 23 20h44l16-37 16 37h42l23-14 16 14h73"/></svg>';

// Post and Now pages still use the original rig artwork.
export function chromaRig(){return `<div class="cm-rig" aria-hidden="true"><div class="cm-orbit cm-orbit--a"></div><div class="cm-orbit cm-orbit--b"></div><div class="cm-burst cm-burst--red">${signalDisc}</div><div class="cm-monitor"><div class="cm-monitor-side"></div><div class="cm-monitor-front"><div class="cm-window-bar"><span>CHROMA / SIGNAL 001</span><b>− □ ×</b></div>${mosaic(24)}<div class="cm-screen"><div class="cm-screen-top"><span>FULL SPECTRUM</span><i>∞</i></div><div class="cm-screen-word"><span class="cm-channel-cpu">CPU</span><span class="cm-channel-gpu">GPU</span><span class="cm-channel-ram">RAM</span></div><div class="cm-screen-wave">${wave}</div><div class="cm-screen-bottom"><span>ART / SIGNAL STUDY</span><b>+ + +</b></div></div><div class="cm-monitor-foot"><span>EVERY BIT. IN COLOR.</span><i></i></div></div></div><div class="cm-floating cm-floating--frame"><div>FRAME LAB <b>↗</b></div><strong>FPS<span>FOLLOW THE FRAME.</span></strong>${mosaic(12)}</div><div class="cm-floating cm-floating--chip"><span>LOCAL FIRST</span><div class="cm-chip">C<span>01</span></div><small>HARDWARE OBSERVATORY</small></div><div class="cm-burst cm-burst--yellow">${signalDisc}<b>∞</b></div><div class="cm-keyboard"><span>CTRL</span><span>ALT</span><span>COLOR ↗</span></div><span class="cm-coordinate cm-coordinate--a">X : 006<br>Y : 2000</span><span class="cm-coordinate cm-coordinate--b">SIGNAL REMIX<br>CHEFZC / 2026</span></div>`;}

// The room's pixel strip: a row of signal tiles that runs the full width of the room.
const pixels=(count=96)=>`<div class="chx-pixels" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="--tile:${['#fff000','#00edff','#ff273a','#e9f2ff','#0a1a8f','#fff000','#173dff'][(i*5+(i>>3))%7]}"></i>`).join('')}</div>`;
const views={pro:{zh:'专业模式',en:'PRO',caption:['专业模式 · 英文与中文均来自实际安装版截图','PRO · Actual installed-app captures in Chinese and English']},simple:{zh:'极简模式',en:'Simple',caption:['极简模式 · 实际安装版中文界面','Simple · Actual installed application, Chinese interface']},mini:{zh:'桌面小窗',en:'Mini',caption:['桌面置顶小窗 · 真实界面，不是游戏内 OSD','Floating desktop mini view · Actual interface, not an in-game OSD']}};
function captureSrc(view){return `./assets/projects/chroma/${view==='pro'?`pro-${getLanguage()==='en'?'en':'zh'}`:view==='simple'?'simple-zh':'mini'}.png`;}
// A chrome bezel around the real application capture. The three keys swap the screenshot.
export function chromaCapture(view='pro') {return `<section class="chx-capture" data-chroma-preview="${view}"><div class="chx-bezel"><div class="chx-bezel-bar"><span class="chx-pixel">CHROMA.EXE</span><span class="chx-bezel-label">${c('真实软件界面','Actual application')}</span><div class="chx-keys" role="group" aria-label="${c('选择界面截图','Choose an application screenshot')}">${Object.entries(views).map(([id,v])=>`<button type="button" data-chroma-view="${id}" aria-pressed="${id===view}">${c(v.zh,v.en)}</button>`).join('')}</div></div><figure class="chx-screen"><div class="chx-glass"><img src="${captureSrc(view)}" width="${view==='mini'?410:1480}" height="${view==='mini'?351:962}" alt="${c(...views[view].caption)}" loading="lazy" decoding="async"></div><figcaption><span data-chroma-caption>${c(...views[view].caption)}</span><span>${c('截图为当时读数，不是访客硬件数据','Recorded readings, not visitor hardware data')}</span></figcaption></figure><div class="chx-bezel-foot" aria-hidden="true"><span class="chx-pixel">Y2K SIGNAL REMIX / 001</span><span class="chx-pixel chx-ticker">HARDWARE OBSERVATORY / FULL SPECTRUM / FRAME LAB: FOLLOW THE FRAME / LOCAL FIRST</span><span class="chx-led"></span></div></div></section>`;}
export function changeChromaView(button){const host=button.closest('[data-chroma-preview]');const view=button.dataset.chromaView;if(!host||!views[view])return;host.dataset.chromaPreview=view;host.querySelectorAll('[data-chroma-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const img=host.querySelector('img');img.src=captureSrc(view);img.alt=c(...views[view].caption);img.width=view==='mini'?410:1480;img.height=view==='mini'?351:962;host.querySelector('[data-chroma-caption]').textContent=c(...views[view].caption);}
const channels={cpu:['从占用率，到核心温度。','From load to core temperatures.','逻辑线程、频率、功耗与可用传感器，给好奇心更多线索。','Logical threads, clocks, power and available sensors give curiosity more to follow.'],gpu:['让每一帧，都有迹可循。','Find the story in every frame.','GPU、显存与 PresentMon 帧分析入口。真实帧捕获取决于 ETW 权限；游戏内效果尚未验证。','GPU, VRAM and a PresentMon frame lab. Capture depends on ETW access; actual in-game behavior remains unverified.'],ram:['把这一刻，留成一份记录。','Keep a record of this moment.','内存、磁盘、网络、十分钟趋势，以及可以导出的会话记录。','Memory, disks, network, ten-minute trends and exportable session records.']};
const channelCopy=id=>`<h4>${c(channels[id][0],channels[id][1])}</h4><p>${c(channels[id][2],channels[id][3])}</p>`;
// Channels recolour the whole room: CPU blue, GPU signal red, RAM yellow.
export function changeChromaChannel(button){const root=button.closest('.xr--chroma');if(!root)return;const id=button.dataset.chromaChannelButton;if(!channels[id])return;root.dataset.chromaChannel=id;root.dataset.theme=id==='ram'?'light':'dark';root.querySelectorAll('[data-chroma-channel-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const copy=root.querySelector('[data-chroma-copy]');if(copy)copy.innerHTML=channelCopy(id);}
const actions=()=>`<div class="xr-actions">${linkButton({href:chromaRelease,text:c('下载 Windows 版','Download for Windows'),iconName:'arrow-down',primary:true})}${linkButton({href:chromaRepo,text:'GitHub'})}${linkButton({href:'./post.html?article=chroma',text:c('信号手记','Signal notes'),external:false})}</div>`;
const project=()=>localizeProject(projects.find(p=>p.id==='chroma'));
const spec=p=>specList([[label.exhibit(),'No. 06'],[label.category(),p.category],[label.version(),'<span class="xr-data">0.1.0</span> / Early access'],[label.platform(),'Windows x64'],[label.stack(),tagLine(p.tags)]]);

export function chromaCard(){const p=project();return `<article class="exhibit xr xr--chroma" id="project-chroma" data-chroma-channel="cpu" data-theme="dark">${pixels()}<div class="xr-inner"><div class="xr-hero"><div class="xr-copy">${roomTitle('CHROMA','06')}<p class="chx-slogan chx-pixel">EVERY BIT.<br>IN COLOR.</p><p class="xr-sub">${c('给电脑的心跳，调一套新颜色。','Your machine. In full color.')}</p><p class="xr-lede">${c('CPU、GPU、传感器与每一段性能记录。一座留在本机的硬件观测站，用像素、金属和不怕张扬的颜色，把信号变得看得见。','CPU, GPU, sensors and the story of a session. A local hardware observatory in pixels, chrome and unapologetic colour. Follow the signal.')}</p>${spec(p)}${actions()}<div class="xr-actions xr-actions--inside">${insideButton('chroma',c('打开观测站','Inside the observatory'))}</div></div><div class="xr-stage chx-stage"><div class="chx-discs" aria-hidden="true"><span class="chx-disc chx-disc--red">${signalDisc}</span><span class="chx-disc chx-disc--yellow">${signalDisc}</span></div>${chromaCapture()}</div></div><section class="chx-remix" aria-labelledby="chroma-remix-title"><span class="chx-remix-tag chx-pixel" aria-hidden="true">01 / COLOR CHANNEL</span><h4 class="chx-remix-title" id="chroma-remix-title">${c('切换一道信号。','Remix the signal.')}</h4><div class="chx-channels" role="group" aria-label="${c('展柜配色与功能视角','Exhibit colour and feature perspective')}">${['cpu','gpu','ram'].map((v,i)=>`<button type="button" data-chroma-channel-button="${v}" aria-pressed="${i===0}"><small class="chx-pixel">0${i+1}</small><span>${v.toUpperCase()}</span></button>`).join('')}</div><div class="chx-channel-copy" data-chroma-copy aria-live="polite">${channelCopy('cpu')}</div><div class="chx-scope" data-chroma-scope aria-hidden="true"><canvas></canvas><span class="chx-pixel" data-scope-label>SIMULATED SIGNAL / CPU</span><span class="chx-pixel">CHROMA.EXE / LIVE TILE</span></div></section><ul class="chx-caps"><li><b>LOCAL</b><span>${c('读数留在本机','Your readings stay local')}</span></li><li><b>SIMPLE ${icon('arrow-right')} PRO</b><span>${c('从一眼看懂，到继续研究','From a glance to a closer look')}</span></li><li><b>中 / EN</b><span>${c('跟随系统，也记住你的选择','Follows your system and your choice')}</span></li></ul><footer class="xr-foot"><span>${c('视觉装置 / 展柜不读取访客硬件','Visual installation / No visitor hardware access')}</span><span class="chx-pixel">MADE OF SIGNALS. MADE WITH CURIOSITY.</span><span>CHEFZC © 2026</span></footer></div></article>`;}

export function chromaDetail(view='pro'){const p=project();return `<div class="xd xd--chroma">${pixels(64)}<header class="xd-head">${roomTitle('CHROMA','06',{tag:'h2',id:'dialog-title'})}<p class="xr-sub">${c('每一道信号，都有自己的颜色。','Every signal has a colour of its own.')}</p>${specList([[label.category(),esc(p.category)],[c('系列','Edition'),'Signal remix'],[label.platform(),'Windows x64'],[label.version(),'<span class="xr-data">0.1.0</span> / Early access'],[label.stack(),tagLine(p.tags)]])}</header>${chromaCapture(view)}<div class="xd-copy"><section><span class="xd-step">01 / The observatory</span><div><h3>${c('想一眼看懂，也想仔细研究。','A quick glance. A closer look.')}</h3><p>${c('极简模式看 CPU / GPU 占用率和温度；专业模式展开线程、内存、磁盘、网络、传感器搜索与收藏。十分钟趋势、一小时内存会话，导出 CSV / JSON，把这一刻带走。','Simple mode shows CPU/GPU utilization and temperatures. PRO opens logical threads, memory, disks, network and searchable sensors with favorites. Ten-minute trends and one-hour in-memory sessions export to CSV / JSON.')}</p></div></section><section><span class="xd-step">02 / Real signals</span><div><h3>${c('颜色可以热闹，读数必须诚实。','Expressive colour. Honest readings.')}</h3><p>${c('采集在 Windows 桌面端进行，不上传遥测。缺失读数保留为空，过期传感器会标记失效。可选 CPU 驱动与只读服务由安装向导说明；帧分析需要 ETW 权限。桌面小窗不是游戏内 OSD。','Collection runs locally in the Windows app without telemetry uploads. Missing readings remain empty and stale sensors expire. Setup explains the optional CPU driver and read-only service. Frame analysis requires ETW access. Mini view is a desktop window, not an in-game OSD.')}</p></div></section></div><p class="xd-note">${c('0.1.0 为早期版本，Windows 安装包与便携包未签名。已完成基础数据测试、构建与本机采集检查；跨硬件覆盖、真实游戏内 FPS 和长时间压力测试尚未验证。会话需在关闭前导出。','0.1.0 is early access; Windows binaries are unsigned. Basic calculation tests, build and local collection checks passed. Cross-hardware coverage, actual in-game FPS and prolonged stress testing remain unverified. Export sessions before closing.')}</p><div class="xd-actions">${actions()}</div></div>`;}
// Post cover / hero and Now window, series plate (flow-windows-b.css): a flat pixel signal meter in the
// remix colours (white, cyan, yellow, red from low to high), the headline, one line, one data line.
const windowMeter=()=>{const heights=[4,6,3,7,5,6,2,5],tone=r=>r<3?'#e9f2ff':r<5?'#00edff':r<6?'#fff000':'#ff273a';return `<svg class="wb-meter" viewBox="0 0 101 88" preserveAspectRatio="xMidYMax meet" aria-hidden="true">${heights.map((h,c)=>Array.from({length:7},(_,r)=>`<rect x="${c*13}" y="${(6-r)*13}" width="10" height="10" rx="1" fill="${r<h?tone(r):'#ffffff'}"${r<h?'':' fill-opacity=".12"'}/>`).join('')).join('')}</svg>`;};
const chromaPlate=(format,mark,line,data)=>`<div class="${format==='tall'?'milestone-art':'post-art'} wb wb--${format} wb--chroma" aria-hidden="true"><div class="wb-motif">${windowMeter()}</div><div class="wb-type"><strong class="wb-mark">${mark}</strong><span class="wb-line">${line}</span></div><div class="wb-data"><span>${data[0]}</span><span>${data[1]}</span></div></div>`;
export function chromaPostArt(){return chromaPlate('wide','EVERY BIT.<br>IN COLOR.','Turn curiosity all the way up.',['Field note 009<em class="wb-more"> / CHROMA, signal remix</em>','0.1.0']);}
export function chromaNowArt(){return chromaPlate('tall','FULL<br>COLOR.','Every bit. In color.',['CHROMA.EXE / signal remix','0.1.0']);}
